// ================= DOM =================
const $ = (id) => document.getElementById(id);
const htmlEl = document.documentElement;
const themeToggleBtn = $('theme-toggle');
const langSelect = $('lang-select');
const LANG_FLAG_META = { mn: { img: 'data:image/png;base64,', code: 'MN' }, jp: { img: 'data:image/png;base64,', code: 'JP' }, en: { img: 'data:image/png;base64,', code: 'EN' } };
const menuBtn = $('menu-btn');
const closeBtn = $('close-btn');
const mobileMenu = $('mobile-menu');
const overlay = $('overlay');
const homeView = $('home-view');
const checkoutView = $('checkout-view');
const authModal = $('auth-modal');
const loginForm = $('login-form');
const registerForm = $('register-form');
const tabLogin = $('tab-login');
const tabRegister = $('tab-register');
const productModal = $('product-modal');
const cartModal = $('cart-modal');
const successModal = $('success-modal');
const favoritesModal = $('favorites-modal');
const orderGuideModal = $('order-guide-modal');
const loginPrompt = $('login-prompt');
const productsWrapper = $('products-wrapper');
const productGrid = $('product-grid');
const productCount = $('product-count');
const cartBadge = $('cart-badge');
const cartItemsContainer = $('cart-items-container');
const cartSummary = $('cart-summary');
const checkoutItems = $('checkout-items');
const checkoutSubtotal = $('checkout-subtotal');
const checkoutWeight = $('checkout-weight');
const checkoutCargo = $('checkout-cargo');
const checkoutTotal = $('checkout-total');
const checkoutExchange = $('checkout-exchange');
const userBtn = $('user-btn');
const mobileLoginLink = $('mobile-login-link');
const mobileLoginLabel = $('mobile-login-label');
const toastContainer = $('toast-container');

const LANG_META = { mn: 'mn', en: 'en', jp: 'ja' };

// ================= INIT =================
function init() {
    if (currentLang === 'ja') currentLang = 'jp';
    if (!translations[currentLang]) currentLang = 'mn';
    htmlEl.setAttribute('data-theme', currentTheme);
    updateThemeIcon();
    langSelect.value = currentLang;
    applyLanguage();
    updateAuthUI();
    updateCartBadge();
    renderProducts();
    setupEventListeners();
    syncMenuControls();
    initSupabase();
}
init();

// ================= TOAST =================
function showToast(message, type = 'success', duration = 2800) {
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    const icons = { success: '✓', error: '✕', info: 'ℹ', warning: '⚠' };
    toast.innerHTML = `<span class="toast-icon">${icons[type] || '✓'}</span><span class="toast-msg"></span>`;
    toast.querySelector('.toast-msg').textContent = message;
    toastContainer.appendChild(toast);
    requestAnimationFrame(() => toast.classList.add('show'));
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 300);
    }, duration);
}

// ================= EVENTS =================
function setupEventListeners() {
    themeToggleBtn.addEventListener('click', toggleTheme);

    fillContactInfo();

    const toTopBtn = $('to-top-btn');
    if (toTopBtn) {
        window.addEventListener('scroll', () => {
            toTopBtn.classList.toggle('visible', window.scrollY > 400);
        }, { passive: true });
    }

    langSelect.addEventListener('change', (e) => setLanguage(e.target.value));

    const langFlagBtn = $('lang-flag-btn');
    if (langFlagBtn) langFlagBtn.addEventListener('click', (e) => { e.stopPropagation(); toggleLangFlag(); });
    document.addEventListener('click', (e) => {
        const wrap = $('lang-flag');
        if (wrap && !wrap.contains(e.target)) toggleLangFlag(false);
    });

    document.querySelectorAll('.mobile-nav-links a').forEach(link => {
        link.addEventListener('click', () => toggleMobileMenu(false));
    });

    menuBtn.addEventListener('click', () => toggleMobileMenu(true));
    closeBtn.addEventListener('click', () => toggleMobileMenu(false));
    overlay.addEventListener('click', () => toggleMobileMenu(false));

    // Сонгосон брэндэд байхгүй ангиллын чипийг нуух (жишээ нь MK-д хүүхэд байхгүй)
    function updateCatChips() {
        document.querySelectorAll('.cat-chip').forEach(chip => {
            const cat = chip.dataset.cat;
            if (cat === 'all' || currentBrandFilter === 'all') { chip.style.display = ''; return; }
            chip.style.display = PRODUCTS.some(p => productInFilter(p, currentBrandFilter) && p.cat === cat) ? '' : 'none';
        });
    }

    function renderCatChips() {
        const cf = $('category-filter');
        if (!cf) return;
        const t = translations[currentLang];
        const defs = currentBrandFilter === 'beauty'
            ? [['all', 'brand_all'], ['skin', 'cat_skin'], ['makeup', 'cat_makeup'], ['sun', 'cat_sun']]
            : [['all', 'brand_all'], ['men', 'cat_men'], ['women', 'cat_women'], ['kids', 'cat_kids']];
        cf.innerHTML = defs.map(([cat, key]) => `<button class="cat-chip${currentCategory === cat ? ' active' : ''}" data-cat="${cat}" data-i18n="${key}">${t[key] || cat}</button>`).join('');
        cf.querySelectorAll('.cat-chip').forEach(chip => {
            chip.addEventListener('click', () => {
                cf.querySelectorAll('.cat-chip').forEach(c => c.classList.remove('active'));
                chip.classList.add('active');
                currentCategory = chip.dataset.cat;
                renderProducts();
            });
        });
        cf.classList.toggle('hidden', currentBrandFilter === 'all' || currentBrandFilter === 'ginza');
        updateCatChips();
        const officialLink = $('brand-official-link');
        const officialUrl = brandLogoSelected ? BRAND_OFFICIAL_URLS[currentBrandFilter] : '';
        if (officialLink) {
            officialLink.hidden = !officialUrl;
            if (officialUrl) {
                officialLink.href = officialUrl;
                officialLink.textContent = `🔗 ${t.official_store}`;
            }
        }
    }

    document.querySelectorAll('.brand-tab').forEach(tab => {
        tab.addEventListener('click', () => {
            document.querySelectorAll('.brand-tab').forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            currentBrandFilter = tab.dataset.brand;
            brandLogoSelected = currentBrandFilter !== 'all';
            currentCategory = 'all';
            renderCatChips();
            renderProducts();
            scrollToProducts();
        });
    });

    const brandTabsEl = $('brand-tabs');
    if (brandTabsEl) {
        brandTabsEl.addEventListener('scroll', updateBrandArrows, { passive: true });
        window.addEventListener('resize', updateBrandArrows);
        updateBrandArrows();
    }

    renderCatChips();

    $('search-input').addEventListener('input', (e) => {
        currentSearchQuery = e.target.value.toLowerCase().trim();
        renderProducts();
    });

    [authModal, productModal, cartModal, successModal, favoritesModal, orderGuideModal].forEach(modal => {
        modal.addEventListener('click', (e) => {
            if (e.target === modal) closeModal(modal);
        });
    });

    // ESC товчоор modal хаах
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            [authModal, productModal, cartModal, successModal, favoritesModal, orderGuideModal].forEach(closeModal);
            toggleMobileMenu(false);
        }
    });
}

// ================= THEME =================
function toggleTheme() {
    currentTheme = currentTheme === 'dark' ? 'light' : 'dark';
    htmlEl.setAttribute('data-theme', currentTheme);
    localStorage.setItem('theme', currentTheme);
    updateThemeIcon();
    syncMenuControls();
}

function setThemeMode(mode) {
    currentTheme = mode;
    htmlEl.setAttribute('data-theme', mode);
    localStorage.setItem('theme', mode);
    updateThemeIcon();
    syncMenuControls();
}

function setLanguage(lang) {
    lang = lang === 'ja' ? 'jp' : lang;
    if (!translations[lang]) lang = 'mn';
    currentLang = lang;
    localStorage.setItem('lang', lang);
    if (langSelect) langSelect.value = lang;
    applyLanguage();
    const officialLink = $('brand-official-link');
    if (officialLink && !officialLink.hidden && brandLogoSelected) {
        officialLink.textContent = `🔗 ${(translations[currentLang] || translations.mn).official_store}`;
    }
    renderProducts();
    renderCart();
    renderCheckout();
    if (productModal.classList.contains('active') && selectedProduct) {
        openProductDetail(selectedProduct.id, true);
    }
    syncMenuControls();
}

// Desktop header language control with real flag images (Windows browsers cannot render flag emoji in the native <select>)
function syncLangFlag() {
    const meta = LANG_FLAG_META[currentLang];
    const img = $('lang-flag-current');
    if (!img || !meta) return;
    img.src = meta.img;
    $('lang-flag-code').textContent = meta.code;
    document.querySelectorAll('#lang-flag-menu [data-lang]').forEach(b => {
        b.classList.toggle('active', b.dataset.lang === currentLang);
    });
}
function toggleLangFlag(force) {
    const menu = $('lang-flag-menu');
    if (!menu) return;
    const show = typeof force === 'boolean' ? force : menu.hidden;
    menu.hidden = !show;
    const btn = $('lang-flag-btn');
    if (btn) btn.setAttribute('aria-expanded', String(show));
}
function chooseLangFlag(lang) {
    setLanguage(lang);
    toggleLangFlag(false);
}

function syncMenuControls() {
    document.querySelectorAll('.lang-icon-btn[data-lang]').forEach(b => {
        b.classList.toggle('active', b.dataset.lang === currentLang);
    });
    syncLangFlag();
    const themeBtn = $('menu-theme-btn');
    if (themeBtn) themeBtn.innerHTML = currentTheme === 'dark' ? ICON_MOON : ICON_SUN;
}

function updateThemeIcon() {
    themeToggleBtn.innerHTML = currentTheme === 'dark' ? ICON_SUN : ICON_MOON;
}

// ================= LANGUAGE (САЙЖРУУЛСАН) =================
function applyLanguage() {
    const t = translations[currentLang] || translations.mn;

    // 1. html lang attribute
    htmlEl.setAttribute('lang', LANG_META[currentLang] || 'mn');

    // 2. Бүх data-i18n текст
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (t[key] !== undefined) el.textContent = t[key];
    });

    // 3. Бүх data-i18n-placeholder
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (t[key] !== undefined) el.setAttribute('placeholder', t[key]);
    });

    // 4. Бүх data-i18n-aria
    document.querySelectorAll('[data-i18n-aria]').forEach(el => {
        const key = el.getAttribute('data-i18n-aria');
        if (t[key] !== undefined) el.setAttribute('aria-label', t[key]);
    });

    // 5. Mobile login link тусгай
    if (mobileLoginLabel) {
        mobileLoginLabel.textContent = isLoggedIn
            ? (currentLang === 'jp' ? 'ログアウト' : currentLang === 'en' ? 'Logout' : 'Гарах')
            : t.btn_login;
    }

    // 6. Search input placeholder
    const searchInput = $('search-input');
    if (searchInput) searchInput.placeholder = t.search_placeholder;

    // 7. Динамик контентыг дахин render
    updateAuthUI();
    renderProducts();
    if (cartModal.classList.contains('active')) renderCart();
    if (checkoutView.classList.contains('active')) renderCheckout();
    if (successModal.classList.contains('active')) renderSuccessMessage();

    // 8. Brand tabs дахин render (текст солигдох)
    const activeBrand = document.querySelector('.brand-tab.active')?.dataset.brand || 'all';
    document.querySelectorAll('.brand-tab').forEach(tab => {
        if (tab.dataset.brand === 'all') tab.textContent = t.brand_all;
        tab.classList.toggle('active', tab.dataset.brand === activeBrand);
    });
}

// ================= MOBILE MENU =================
function toggleMobileMenu(open) {
    mobileMenu.classList.toggle('active', open);
    overlay.classList.toggle('active', open);
    mobileMenu.setAttribute('aria-hidden', !open);
}

function toggleBrandSubmenu(event) {
    if (event) event.stopPropagation();
    const sub = document.getElementById('brand-submenu');
    const btn = document.getElementById('brand-submenu-toggle');
    if (!sub || !btn) return;
    const open = sub.classList.toggle('open');
    btn.classList.toggle('open', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
}

function selectBrandFromMenu(brand) {
    if (typeof navigateTo === 'function') navigateTo('home');
    let tab = null;
    document.querySelectorAll('.brand-tab').forEach(t => { if (t.dataset.brand === brand) tab = t; });
    if (tab) tab.click();
    toggleMobileMenu(false);
    const sec = document.getElementById('products');
    if (sec) setTimeout(() => sec.scrollIntoView({ behavior: 'smooth' }), 60);
}

// ================= AUTH =================
async function handleUserClick() {
    if (isLoggedIn) {
        const t = translations[currentLang];
        if (confirm(t.msg_confirm_logout)) {
            if (USE_SUPABASE && sb) { try { await sb.auth.signOut(); } catch (err) { } }
            isLoggedIn = false;
            currentUser = null;
            localStorage.setItem('isLoggedIn', 'false');
            updateAuthUI();
            renderProducts();
            showToast(t.msg_logout_success, 'info');
        }
    } else {
        openAuthModal('login');
    }
}

async function applySession(session) {
    if (!session || !session.user) {
        currentUser = null;
        isLoggedIn = false;
        localStorage.setItem('isLoggedIn', 'false');
        updateAuthUI();
        renderProducts();
        return;
    }
    let profile = null;
    try {
        const { data } = await sb.from('profiles').select('name, role').eq('id', session.user.id).single();
        profile = data;
    } catch (err) { /* profile байхгүй бол энгийн хэрэглэгч */ }
    currentUser = {
        id: session.user.id,
        email: session.user.email,
        name: (profile && profile.name) || (session.user.user_metadata && session.user.user_metadata.name) || '',
        role: (profile && profile.role) || 'user'
    };
    isLoggedIn = true;
    localStorage.setItem('isLoggedIn', 'true');
    updateAuthUI();
    renderProducts();
}

async function initSupabase() {
    if (!USE_SUPABASE || !window.supabase) return;
    sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
    try {
        const { data } = await sb.auth.getSession();
        if (data && data.session) await applySession(data.session);
    } catch (err) { /* сүлжээний алдаа бол демо горимоор үлдэнэ */ }
    sb.auth.onAuthStateChange(async (event, session) => {
        if (event === 'PASSWORD_RECOVERY') openResetForm();
        else if (event === 'SIGNED_OUT') await applySession(null);
        else if (event === 'SIGNED_IN' && session) await applySession(session);
    });
}

async function handleForgotPassword() {
    const t = translations[currentLang];
    if (!(USE_SUPABASE && sb)) { showToast(t.msg_reset_unavailable, 'info'); return; }
    const email = $('login-email').value.trim();
    if (!email) { showToast(t.msg_fill_email, 'warning'); return; }
    const { error } = await sb.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.origin + window.location.pathname
    });
    if (error) { showToast(error.message, 'error'); return; }
    showToast(t.msg_reset_sent, 'success');
}

function openResetForm() {
    authModal.classList.add('active');
    loginForm.classList.remove('active');
    registerForm.classList.remove('active');
    $('reset-form').classList.add('active');
    document.body.style.overflow = 'hidden';
}

async function handleResetPassword(e) {
    e.preventDefault();
    const t = translations[currentLang];
    if (!(USE_SUPABASE && sb)) return;
    const password = $('reset-password').value;
    const { error } = await sb.auth.updateUser({ password });
    if (error) { showToast(error.message, 'error'); return; }
    $('reset-form').classList.remove('active');
    $('reset-form').reset();
    closeAuthModal();
    showToast(t.msg_password_updated, 'success');
}

function openAuthModal(tab = 'login') {
    if (isLoggedIn) {
        showToast(translations[currentLang].msg_already_logged, 'info');
        return;
    }
    authModal.classList.add('active');
    switchAuthTab(tab);
    document.body.style.overflow = 'hidden';
}

function closeAuthModal() {
    authModal.classList.remove('active');
    document.body.style.overflow = '';
    const rf = $('reset-form');
    if (rf) rf.classList.remove('active');
}

function switchAuthTab(tab) {
    const isLogin = tab === 'login';
    tabLogin.classList.toggle('active', isLogin);
    tabRegister.classList.toggle('active', !isLogin);
    loginForm.classList.toggle('active', isLogin);
    registerForm.classList.toggle('active', !isLogin);
    const rf = $('reset-form');
    if (rf) rf.classList.remove('active');
}

async function handleLogin(e) {
    e.preventDefault();
    const t = translations[currentLang];
    if (USE_SUPABASE && sb) {
        const email = $('login-email').value.trim();
        const password = $('login-password').value;
        const { data, error } = await sb.auth.signInWithPassword({ email, password });
        if (error) { showToast(t.msg_login_error, 'error'); return; }
        await applySession(data.session);
        closeAuthModal();
        showToast(t.msg_login_success, 'success');
        loginForm.reset();
        return;
    }
    isLoggedIn = true;
    localStorage.setItem('isLoggedIn', 'true');
    updateAuthUI();
    closeAuthModal();
    renderProducts();
    showToast(t.msg_login_success, 'success');
    loginForm.reset();
}

async function handleRegister(e) {
    e.preventDefault();
    const t = translations[currentLang];
    if (USE_SUPABASE && sb) {
        const name = $('reg-name').value.trim();
        const email = $('reg-email').value.trim();
        const password = $('reg-password').value;
        const { data, error } = await sb.auth.signUp({ email, password, options: { data: { name } } });
        if (error) { showToast(error.message, 'error'); return; }
        if (data.session) {
            await applySession(data.session);
            closeAuthModal();
            showToast(t.msg_register_success, 'success');
        } else {
            closeAuthModal();
            showToast(t.msg_check_email, 'info');
        }
        registerForm.reset();
        return;
    }
    isLoggedIn = true;
    localStorage.setItem('isLoggedIn', 'true');
    updateAuthUI();
    closeAuthModal();
    renderProducts();
    showToast(t.msg_register_success, 'success');
    registerForm.reset();
}

function updateAuthUI() {
    const t = translations[currentLang];
    const adminItem = $('admin-nav-item');
    if (adminItem) adminItem.style.display = (isLoggedIn && currentUser && currentUser.role === 'admin') ? '' : 'none';
    const adminItemDesktop = $('admin-nav-item-desktop');
    if (adminItemDesktop) adminItemDesktop.style.display = (isLoggedIn && currentUser && currentUser.role === 'admin') ? '' : 'none';
    if (isLoggedIn) {
        userBtn.title = currentLang === 'jp' ? 'ログアウト' : currentLang === 'en' ? 'Logout' : 'Гарах';
        if (mobileLoginLabel) mobileLoginLabel.textContent = currentLang === 'jp' ? 'ログアウト' : currentLang === 'en' ? 'Logout' : 'Гарах';
        loginPrompt.classList.add('hidden');
        productsWrapper.classList.remove('hidden');
    } else {
        userBtn.title = t.btn_login;
        if (mobileLoginLabel) mobileLoginLabel.textContent = t.btn_login;
        loginPrompt.classList.add('hidden');
        productsWrapper.classList.remove('hidden');
    }
    requestAnimationFrame(updateBrandArrows);
}

