function cnameL(c, lang) {
    if (!c) return c;
    if (lang === 'jp') return c;
    const tr = COLOR_TR[c];
    if (!tr) return c;
    return lang === 'mn' ? (tr.mn || tr.en || c) : (tr.en || c);
}
function cname(c) { return cnameL(c, currentLang); }

function iname(item) {
    return pname(PRODUCTS.find(x => x.id === item.id)) || item.name || '';
}

function productInFilter(p, f) {
    if (f === 'all') return !p.sec && !p.brandOnly;
    if (f === 'beauty') return p.sec === 'beauty';
    if (f === 'ginza') return p.sec === 'ginza';
    return p.brand === f;
}

